-- Editorial conversation starters, not fictional member testimonials.
-- Stable IDs make this release idempotent; never overwrite member interactions.
INSERT INTO public.community_posts(id,author_id,author_name,author_badge,category,title,content,likes_count,comments_count,comments)
SELECT md5('coremotion-editorial-topics-v1:' || title)::uuid,NULL,'CoreMotion','Pauta editorial',category,title,content,0,0,'[]'::jsonb
FROM (VALUES
('treino','Corrida: como encontrar um ritmo confortável no começo?','Nem todo treino precisa terminar no limite. Para quem está começando, alternar caminhada e corrida pode ser uma opção a discutir com um profissional. Como vocês organizam a evolução e percebem quando precisam descansar? Compartilhem experiências, sem transformar a rotina de outra pessoa em regra.'),
('treino','Musculação: técnica, carga ou constância — qual foi seu maior aprendizado?','Anotar exercícios e perceber a qualidade do movimento ajuda a conversar com quem orienta seu treino. O que mudou sua relação com a musculação? Contem como conciliam evolução e recuperação. Dor persistente merece avaliação profissional, não diagnóstico pelos comentários.'),
('treino','Futebol e futsal: como vocês treinam o pé menos dominante?','Domínio, passe e tomada de decisão aparecem o tempo todo no jogo. Que exercícios vocês praticam para ganhar confiança com os dois pés? Vale compartilhar adaptações para treinar em pouco espaço e sugestões para grupos iniciantes.'),
('treino','Vôlei: comunicação dentro de quadra também se treina','Chamar a bola, combinar a cobertura e conversar depois do ponto fazem parte do jogo coletivo. Como seu grupo organiza a comunicação sem transformar um erro em cobrança excessiva? Quem joga na areia e na quadra percebe diferenças?'),
('equipamento','Ciclismo: o que conferir na bicicleta antes de sair?','Pneus, freios, corrente, iluminação e capacete merecem atenção antes do pedal. Qual é o checklist que vocês usam? Compartilhem também como escolhem rotas e sinalizam ao pedalar em grupo. Ajustes mecânicos e de posição podem exigir avaliação especializada.'),
('equipamento','Tênis esportivo: como escolher sem depender só da aparência?','Modalidade, conforto, ajuste e superfície de uso importam na escolha. Preço alto ou uma tecnologia anunciada não garantem que o modelo será adequado para todo mundo. O que vocês costumam observar ao experimentar? Contem a modalidade e o tipo de uso, sem prometer prevenção de lesões.'),
('duvida','Natação: como lidar com a respiração ao aprender?','Aprender a respirar na água pode exigir tempo e orientação presencial. Que dicas do seu professor ajudaram a ganhar tranquilidade? Quem está começando deve praticar em local supervisionado; não façam desafios de prender a respiração ou treinem sozinhos.'),
('duvida','Lutas: o que você gostaria de saber antes da primeira aula?','Jiu-jítsu, judô, boxe e outras modalidades têm rotinas e equipamentos diferentes. Como foi escolher uma academia acolhedora? Compartilhem dúvidas sobre vestimenta, higiene, regras e respeito aos limites do parceiro. Técnicas de risco precisam de orientação presencial.'),
('duvida','Esporte adaptado: quais barreiras podemos remover nos treinos?','Acessibilidade envolve espaço, comunicação, equipamentos e acolhimento. Que adaptações e atitudes tornaram sua prática mais acessível? Não presumam as necessidades de outra pessoa: ouvir o praticante e buscar orientação qualificada é essencial.'),
('evento','Vai participar da primeira prova? Vamos montar um checklist','Este é um espaço de planejamento, não o anúncio de uma prova específica. O que vocês conferem no regulamento, na retirada do kit, no trajeto e no transporte? Incluam o que aprenderam sobre chegar com antecedência e respeitar os próprios limites.'),
('evento','Como organizar um encontro esportivo seguro e acolhedor?','Para uma corrida em grupo, pedal ou partida entre amigos, que informações precisam estar claras? Modalidade, nível, local público, horário, acessibilidade e condições do espaço ajudam no planejamento. Não publiquem documentos, endereço residencial ou contatos de terceiros sem autorização.'),
('conquista','Pequenas conquistas também merecem espaço','Voltar a se movimentar, aprender um fundamento ou manter uma rotina possível pode ser tão importante quanto um recorde. Qual conquista esportiva você quer compartilhar nesta semana? Não precisa comparar desempenho: a ideia é reconhecer o próprio processo e apoiar os outros.')
) AS topics(category,title,content)
ON CONFLICT(id) DO NOTHING;
